import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const session: ChatSession = {
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}],
};

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const hookCalls = async (reason: unknown) => {
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {
    hooks: {
      onError: async (_session, error) => {
        seen.push(error);
      },
    },
  });
  const rejection = await orchestrator.processMessage(session).then(
    () => 'resolved' as unknown,
    (thrown: unknown) => thrown
  );
  return {seen, rejection};
};

describe('ChatOrchestrator onError cause', () => {
  it('wraps a rejection of undefined in an Error whose cause is undefined and rethrows undefined', async () => {
    const {seen, rejection} = await hookCalls(undefined);

    expect({count: seen.length, isError: seen[0] instanceof Error, hasCause: seen[0] && 'cause' in seen[0], rejection}).toEqual({
      count: 1,
      isError: true,
      hasCause: true,
      rejection: undefined,
    });
  });

  it('keeps the original object as the cause of the wrapper', async () => {
    const reason = {code: 503};

    const {seen} = await hookCalls(reason);

    expect(seen[0]?.cause).toBe(reason);
  });

  it('passes an Error to onError as the same instance', async () => {
    const reason = new Error('real');

    const {seen} = await hookCalls(reason);

    expect(seen[0]).toBe(reason);
  });
});
EOF
